AssistantMessageToolRequest(name='create', tool_call_id='toolu_01QGTjCWW1uzXDXuzJ8ZaWQN', arguments={'file_text': 'const { useState } = React;

const QUESTIONS = [
  {
    id: "q1",
    prompt: "Which of these are statically typed languages?",
    help: "Select all that apply. Static typing means types are checked at compile time.",
    options: ["Python", "TypeScript", "Rust", "JavaScript"],
  },
  {
    id: "q2",
    prompt: "Which languages run primarily on the JVM?",
    options: ["Kotlin", "Swift", "Scala", "Go"],
  },
  {
    id: "q3",
    prompt: "Which languages support first-class functions?",
    options: ["JavaScript", "Haskell", "COBOL", "Python"],
  },
];

function Option({ name, value, checked, onChange }) {
  return (
    <label className={`option${checked ? " selected" : ""}`}>
      <input
        type="checkbox"
        name={name}
        value={value}
        checked={checked}
        onChange={onChange}
      />
      <span className="option-text">{value}</span>
    </label>
  );
}

function Question({ index, question, selected, onToggle }) {
  return (
    <div className="form-field">
      <div className="field-label">
        <span className="field-number">{index + 1}</span>
        <span>{question.prompt}</span>
      </div>
      {question.help && <p className="help-text">{question.help}</p>}
      <div className="options" role="group" aria-label={question.prompt}>
        {question.options.map((opt) => (
          <Option
            key={opt}
            name={question.id}
            value={opt}
            checked={selected.includes(opt)}
            onChange={() => onToggle(question.id, opt)}
          />
        ))}
      </div>
    </div>
  );
}

function Quiz() {
  const [answers, setAnswers] = useState(
    QUESTIONS.reduce((acc, q) => ({ ...acc, [q.id]: [] }), {})
  );
  const [submitted, setSubmitted] = useState(false);

  const handleToggle = (qid, value) => {
    setSubmitted(false);
    setAnswers((prev) => {
      const current = prev[qid];
      const next = current.includes(value)
        ? current.filter((v) => v !== value)
        : [...current, value];
      return { ...prev, [qid]: next };
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  const totalSelected = Object.values(answers).reduce(
    (sum, arr) => sum + arr.length,
    0
  );

  return (
    <form className="quiz-card" onSubmit={handleSubmit} noValidate>
      <header className="quiz-header">
        <h1>Computer Languages Quiz</h1>
        <p>Test your knowledge — multiple answers may be correct per question.</p>
      </header>

      {QUESTIONS.map((q, i) => (
        <Question
          key={q.id}
          index={i}
          question={q}
          selected={answers[q.id]}
          onToggle={handleToggle}
        />
      ))}

      <div className="actions">
        <button type="submit" className="submit-btn">
          Submit answers
        </button>
      </div>

      {submitted && (
        <div className="results" role="status">
          Thanks! You selected {totalSelected} answer
          {totalSelected === 1 ? "" : "s"} across {QUESTIONS.length} questions.
        </div>
      )}
    </form>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<Quiz />);
